ALTER TABLE "core"."staff_location_period" DROP CONSTRAINT "staff_location_period_month_check";--> statement-breakpoint
ALTER TABLE "profitability"."fixed_cost_period" DROP CONSTRAINT "profitability_period_month_check";--> statement-breakpoint
ALTER TABLE "profitability"."fixed_cost" DROP CONSTRAINT "profitability_cost_end_check";--> statement-breakpoint
ALTER TABLE "core"."staff_location_period" ADD CONSTRAINT "staff_location_period_month_check" CHECK (isfinite("core"."staff_location_period"."from_month") and extract(day from "core"."staff_location_period"."from_month") = 1 and ("core"."staff_location_period"."until_month" is null or (isfinite("core"."staff_location_period"."until_month") and extract(day from "core"."staff_location_period"."until_month") = 1 and "core"."staff_location_period"."until_month" > "core"."staff_location_period"."from_month")));--> statement-breakpoint
ALTER TABLE "profitability"."fixed_cost_period" ADD CONSTRAINT "profitability_period_month_check" CHECK (isfinite("profitability"."fixed_cost_period"."from_month") and extract(day from "profitability"."fixed_cost_period"."from_month") = 1 and ("profitability"."fixed_cost_period"."until_month" is null or (isfinite("profitability"."fixed_cost_period"."until_month") and extract(day from "profitability"."fixed_cost_period"."until_month") = 1 and "profitability"."fixed_cost_period"."until_month" > "profitability"."fixed_cost_period"."from_month")));--> statement-breakpoint
ALTER TABLE "profitability"."fixed_cost" ADD CONSTRAINT "profitability_cost_end_check" CHECK ("profitability"."fixed_cost"."end_month" is null or (isfinite("profitability"."fixed_cost"."end_month") and extract(day from "profitability"."fixed_cost"."end_month") = 1));